messages.content:
Tool response:
Tool: search_certified_suv_vehicles
Description: Search Certified Suv Vehicles
Parameters:
    {
      "type": "object",
      "properties": {
        "dealership_name": {
          "type": "string",
          "description": "Name of the dealership to filter vehicles",
          "title": "Dealership Name"
        },
        "max_mileage": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum mileage threshold (default: 30000)",
          "default": 30000,
          "title": "Max Mileage"
        },
        "min_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum price threshold (default: 25000)",
          "default": 25000,
          "title": "Min Price"
        },
        "max_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum price threshold (default: 40000)",
          "default": 40000,
          "title": "Max Price"
        }
      },
      "required": [
        "dealership_name"
      ]
    }
